-- MAGIC ##### Setup
-- MAGIC <pre><code class="language-python"># Parameters
-- MAGIC source_table = "hms_db.orders"      # Hive Metastore table (pre-migration)
-- MAGIC target_table = "uc_catalog.sales.orders"  # Unity Catalog table (post-migration)
-- MAGIC
-- MAGIC #  If you have known volatile columns, list them here to exclude from strict comparisons
