-- MAGIC ##### Schema Parity Checks

-- COMMAND ----------

-- MAGIC %md-sandbox
-- MAGIC ###### Compare Spark Schemas
-- MAGIC <pre><code class="language-python">from pyspark.sql import functions as F
-- MAGIC
-- MAGIC src_df = spark.table(source_table)
-- MAGIC tgt_df = spark.table(target_table)
-- MAGIC
-- MAGIC def schema_signature(df):
-- MAGIC     # Return a list of (name_lower, datatype_simple, nullable) in column order
-- MAGIC     return [(f.name.lower(), f.dataType.simpleString(), f.nullable) for f in df.schema.fields]
-- MAGIC
-- MAGIC src_sig = schema_signature(src_df)
-- MAGIC tgt_sig = schema_signature(tgt_df)
-- MAGIC
-- MAGIC def signature_diff(src_sig, tgt_sig):
-- MAGIC     src_map = {c[0]: c for c in src_sig}
-- MAGIC     tgt_map = {c[0]: c for c in tgt_sig}
-- MAGIC
-- MAGIC     only_in_src = sorted(set(src_map) - set(tgt_map))
-- MAGIC     only_in_tgt = sorted(set(tgt_map) - set(src_map))
-- MAGIC
-- MAGIC     type_or_nullable_mismatch = []
-- MAGIC     for col in sorted(set(src_map).intersection(tgt_map)):
-- MAGIC         s = src_map[col]; t = tgt_map[col]
-- MAGIC         if s[1:] != t[1:]:  # compare (datatype, nullable)
-- MAGIC             type_or_nullable_mismatch.append((col, (s[1], s[2]), (t[1], t[2])))
-- MAGIC
-- MAGIC     order_mismatch = [i for i, (s, t) in enumerate(zip([c[0] for c in src_sig], [c[0] for c in tgt_sig])) if s != t]
-- MAGIC
-- MAGIC     return {
-- MAGIC         "only_in_source": only_in_src,
-- MAGIC         "only_in_target": only_in_tgt,
-- MAGIC         "type_or_nullable_mismatch": type_or_nullable_mismatch,
-- MAGIC         "order_mismatch_indices": order_mismatch,
-- MAGIC     }
-- MAGIC
-- MAGIC schema_diffs = signature_diff(src_sig, tgt_sig)
-- MAGIC schema_diffs
-- MAGIC </code></pre>
-- MAGIC
-- MAGIC Interpreting results:
-- MAGIC - only_in_source / only_in_target: missing/extra columns.
-- MAGIC - type_or_nullable_mismatch: any type or nullability differences to address.
-- MAGIC - order_mismatch_indices: FYI for tools sensitive to column order.
-- MAGIC
-- MAGIC <link href="https://cdnjs.cloudflare.com/ajax/libs/prism/1.29.0/themes/prism.min.css" rel="stylesheet" />
-- MAGIC <script src="https://cdnjs.cloudflare.com/ajax/libs/prism/1.29.0/prism.min.js"></script>
-- MAGIC <script src="https://cdnjs.cloudflare.com/ajax/libs/prism/1.29.0/components/prism-python.min.js"></script>

-- COMMAND ----------

-- MAGIC %md-sandbox
-- MAGIC ###### Partitioning, Properties, and Location
-- MAGIC <pre><code class="language-python"># DESCRIBE DETAIL returns table metadata including properties and partitioning
-- MAGIC src_detail = spark.sql(f"DESCRIBE DETAIL {source_table}").first().asDict()
-- MAGIC tgt_detail = spark.sql(f"DESCRIBE DETAIL {target_table}").first().asDict()
-- MAGIC
-- MAGIC def summarize_detail(d):
-- MAGIC     keys = ["format", "location", "numFiles", "sizeInBytes", "tableType", "name"]
-- MAGIC     return {k: d.get(k) for k in keys}
-- MAGIC
-- MAGIC {"source": summarize_detail(src_detail), "target": summarize_detail(tgt_detail)}
-- MAGIC </code></pre>
